const r = await tools.pwsh({
  description: "Grep goofish html for item fields",
  command: `cd "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts"
$t = Get-Content "_b_xy_lwjz2.html" -Raw -Encoding UTF8
foreach($k in @('soldPrice','price','wantCnt','wantNum','"title"','itemCard','cardData','__INITIAL','window.__','skuTitle')){
  $c = ([regex]::Matches($t,[regex]::Escape($k))).Count
  Write-Host "$k => $c"
}
Write-Host "--- scripts src ---"
[regex]::Matches($t,'<script[^>]*src="([^"]+)"') | Select-Object -First 15 | %{ $_.Groups[1].Value }
`,
  timeoutMs: 60000
});
console.log(r.kind === "foreground" ? r.stdout.text + "\n---ERR---\n" + r.stderr.text : JSON.stringify(r));
